-- Accounts and sync (v1.1, PLAN D225). Triggers append every change to a synced table to
-- sync_outbox, but only while sync_state.record = '1' (signed in and not applying a pull).
-- The triggers below were generated by scripts/sync-triggers.mjs; regenerate them whenever a
-- later migration changes a synced table's columns.

CREATE TABLE sync_outbox (
  seq        INTEGER PRIMARY KEY AUTOINCREMENT,
  tbl        TEXT NOT NULL,
  row_id     TEXT NOT NULL,
  fields     TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE INDEX sync_outbox_row ON sync_outbox(tbl, row_id);

-- record ('0'/'1'), cursor, account, device_id, former_account.
CREATE TABLE sync_state (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
INSERT INTO sync_state (key, value) VALUES ('record', '0');

-- Activity rows need ids that are unique across devices: rebuild with a random text id.
CREATE TABLE task_activity_new (
  id      TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  at      TEXT NOT NULL,
  kind    TEXT NOT NULL,
  detail  TEXT NOT NULL DEFAULT ''
);
INSERT INTO task_activity_new (id, task_id, at, kind, detail)
SELECT lower(hex(randomblob(16))), task_id, at, kind, detail FROM task_activity;
DROP TABLE task_activity;
ALTER TABLE task_activity_new RENAME TO task_activity;
CREATE INDEX task_activity_task ON task_activity(task_id);

