CREATE TRIGGER sync_ins_folders AFTER INSERT ON folders WHEN (SELECT value FROM sync_state WHERE key = 'record') = '1' BEGIN
  INSERT INTO sync_outbox (tbl, row_id, fields, created_at) VALUES ('folders', NEW.id, json_object('id', NEW.id, 'name', NEW.name, 'sort_order', NEW.sort_order, 'collapsed', NEW.collapsed, 'parent_id', NEW.parent_id, 'deleted_at', NULL), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
END;

CREATE TRIGGER sync_upd_folders AFTER UPDATE ON folders WHEN (SELECT value FROM sync_state WHERE key = 'record') = '1' BEGIN
  INSERT INTO sync_outbox (tbl, row_id, fields, created_at)
  SELECT 'folders', NEW.id, f, strftime('%Y-%m-%dT%H:%M:%fZ', 'now') FROM (SELECT json_group_object(k, v) AS f FROM (
      SELECT 'id' AS k, NEW.id AS v WHERE OLD.id IS NOT NEW.id
      UNION ALL SELECT 'name' AS k, NEW.name AS v WHERE OLD.name IS NOT NEW.name
      UNION ALL SELECT 'sort_order' AS k, NEW.sort_order AS v WHERE OLD.sort_order IS NOT NEW.sort_order
      UNION ALL SELECT 'collapsed' AS k, NEW.collapsed AS v WHERE OLD.collapsed IS NOT NEW.collapsed
      UNION ALL SELECT 'parent_id' AS k, NEW.parent_id AS v WHERE OLD.parent_id IS NOT NEW.parent_id)) WHERE f <> '{}';
END;

