  INSERT INTO sync_outbox (tbl, row_id, fields, created_at) VALUES ('folders', OLD.id, json_object('deleted_at', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
END;

