  INSERT INTO sync_outbox (tbl, row_id, fields, created_at) VALUES ('focus_sessions', OLD.id, json_object('deleted_at', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
END;

CREATE TRIGGER sync_ins_rest_days AFTER INSERT ON rest_days WHEN (SELECT value FROM sync_state WHERE key = 'record') = '1' BEGIN
  INSERT INTO sync_outbox (tbl, row_id, fields, created_at) VALUES ('rest_days', NEW.date, json_object('date', NEW.date, 'deleted_at', NULL), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
END;

CREATE TRIGGER sync_upd_rest_days AFTER UPDATE ON rest_days WHEN (SELECT value FROM sync_state WHERE key = 'record') = '1' BEGIN
  INSERT INTO sync_outbox (tbl, row_id, fields, created_at)
  SELECT 'rest_days', NEW.date, f, strftime('%Y-%m-%dT%H:%M:%fZ', 'now') FROM (SELECT json_group_object(k, v) AS f FROM (
      SELECT 'date' AS k, NEW.date AS v WHERE OLD.date IS NOT NEW.date)) WHERE f <> '{}';
END;

CREATE TRIGGER sync_del_rest_days AFTER DELETE ON rest_days WHEN (SELECT value FROM sync_state WHERE key = 'record') = '1' BEGIN
  INSERT INTO sync_outbox (tbl, row_id, fields, created_at) VALUES ('rest_days', OLD.date, json_object('deleted_at', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
END;

CREATE TRIGGER sync_ins_celebrations AFTER INSERT ON celebrations WHEN (SELECT value FROM sync_state WHERE key = 'record') = '1' BEGIN
  INSERT INTO sync_outbox (tbl, row_id, fields, created_at) VALUES ('celebrations', NEW.key, json_object('key', NEW.key, 'at', NEW.at, 'deleted_at', NULL), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
END;

CREATE TRIGGER sync_upd_celebrations AFTER UPDATE ON celebrations WHEN (SELECT value FROM sync_state WHERE key = 'record') = '1' BEGIN
  INSERT INTO sync_outbox (tbl, row_id, fields, created_at)
  SELECT 'celebrations', NEW.key, f, strftime('%Y-%m-%dT%H:%M:%fZ', 'now') FROM (SELECT json_group_object(k, v) AS f FROM (
      SELECT 'key' AS k, NEW.key AS v WHERE OLD.key IS NOT NEW.key
      UNION ALL SELECT 'at' AS k, NEW.at AS v WHERE OLD.at IS NOT NEW.at)) WHERE f <> '{}';
END;

CREATE TRIGGER sync_del_celebrations AFTER DELETE ON celebrations WHEN (SELECT value FROM sync_state WHERE key = 'record') = '1' BEGIN
  INSERT INTO sync_outbox (tbl, row_id, fields, created_at) VALUES ('celebrations', OLD.key, json_object('deleted_at', strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
END;
